"""Bind monthly statements to exact verified acquisition attachment proofs."""
from copy import deepcopy
import json

CONTRACT = json.loads(r'''{"edits":[{"code":"OUTLOOK_FINANCE_ACQUISITION","js":"// Purpose: Attachment Verification Barrier. Keep this deterministic and fail closed.\nconst request = $('Validate Bounded Source Request').first().json;\nconst expected = Array.isArray(request.messages)\n    ? request.messages.flatMap(row => {\n        const message = row?.message && typeof row.message === 'object' ? row.message : row;\n        const messageId = String(row?.message_id || message?.id || '').trim();\n        return (Array.isArray(row?.attachment_inventory) ? row.attachment_inventory : [])\n            .map(attachment => messageId + ':' + attachment.id);\n    })\n    : [];\nconst safeRows = name => {\n    try {\n        return $(name).all().map(item => item.json);\n    }\n    catch {\n        return [];\n    }\n};\n// Use all completed loop iterations, not a named node's first execution.\nconst attachmentRows = $input.all().map(item => item.json)\n    .filter(row => row.attachment_verified === true && !row.attachment_empty);\nconst observed = attachmentRows.map(row => row.attachment_identity || row.source_message_id + ':' + row.source_attachment_id);\nif (new Set(observed).size !== expected.length) {\n    throw new Error('ATTACHMENT_ARCHIVE_COUNT_MISMATCH');\n}\nfor (const identity of expected) {\n    if (!observed.includes(identity)) {\n        throw new Error('ATTACHMENT_ARCHIVE_MISSING:' + identity);\n    }\n}\nconst emailRows = [\n    ...safeRows('Verify Durable Email Evidence Receipt'),\n    ...safeRows('Verify Existing Email Evidence Receipt'),\n].filter(row => row.email_evidence_receipt_verified === true);\nconst expectedEmail = Array.isArray(request.messages)\n    ? request.messages.map(row => {\n        const message = row?.message && typeof row.message === 'object' ? row.message : row;\n        return String(row?.message_id || message?.id) + ':INLINE_BODY';\n    })\n    : [];\nconst observedEmail = emailRows.map(row => row.email_evidence_identity || row.source_message_id + ':INLINE_BODY');\nif (new Set(observedEmail).size !== expectedEmail.length\n    || expectedEmail.some(identity => !observedEmail.includes(identity))) {\n    throw new Error('EMAIL_EVIDENCE_RECEIPT_BARRIER_MISMATCH');\n}\nconst emailArchiveProof = emailRows\n    .map(row => ({\n    source_message_id: String(row.source_message_id || ''),\n    email_evidence_sha256: String(row.email_evidence_sha256 || ''),\n    onedrive_item_id: String(row.onedrive_item_id || ''),\n    email_evidence_identity: String(row.email_evidence_identity || row.source_message_id + ':INLINE_BODY'),\n}))\n    .sort((left, right) => left.source_message_id.localeCompare(right.source_message_id));\nconst archiveIdentityKeys = [...new Set([...observed, ...observedEmail])].sort();\nconst archiveItemIds = [...new Set([...emailArchiveProof, ...attachmentRows]\n        .map(row => row.onedrive_item_id).filter(Boolean))].sort();\nconst first = attachmentRows[0] || emailRows[0] || {};\nreturn [{\n        json: {\n            status: 'ARCHIVED',\n            run_id: request.run_id,\n            source_code: request.source_code,\n            folder_id: request.folder_id,\n            senders: request.senders,\n            subjects: request.subjects,\n            onedrive_parent_id: request.onedrive_parent_id,\n            window_start: request.window_start,\n            run_upper_bound: request.run_upper_bound,\n            matched_count: request.messages.length,\n            onedrive_item_id: first.onedrive_item_id || null,\n            source_message_id: first.source_message_id || null,\n            source_attachment_id: first.source_attachment_id || null,\n            attachment_verification_barrier: 'VERIFIED',\n            attachment_ids_verified: true,\n            attachment_identity_keys: observed,\n            attachments_verified: attachmentRows.length,\n            email_evidence_receipt_barrier: 'VERIFIED',\n            email_evidence_receipts_verified: emailRows.length,\n            email_evidence_identity_keys: observedEmail,\n            archive_identity_keys: archiveIdentityKeys,\n            archive_item_ids: archiveItemIds,\n            attachment_archive_proof: attachmentRows.map(row => ({\n                source_message_id: row.source_message_id,\n                source_attachment_id: row.source_attachment_id,\n                attachment_identity: row.attachment_identity,\n                document_sha256: row.document_sha256 || row.source_sha256,\n                onedrive_item_id: row.onedrive_item_id,\n                is_pdf: row.is_pdf === true,\n                is_inline: row.is_inline === true,\n            })),\n            email_evidence_archive_proof: emailArchiveProof,\n            archive_ready: true,\n            cursor_commit_eligible: false,\n            historical_import: request.historical_import === true,\n            historical_source: request.historical_import === true ? 'ADCB_CASHBACK' : undefined,\n            historical_account_id: request.historical_import === true ? String(request.historical_account_id) : undefined,\n        },\n    }];\n","name":"Attachment Verification Barrier"},{"code":"OUTLOOK_MESSAGE_SWEEP","js":"// Purpose: Aggregate Verified Message Archives. Keep this deterministic and fail closed.\nconst contract = $('Attach Immutable Inventory to Sweep').first().json;\nconst results = $input.all().map(item => item.json);\nconst expectedEmails = contract.messages.map(entry => entry.message_id + ':INLINE_BODY').sort();\nconst expectedAttachments = (contract.attachment_identity_keys || []).slice().sort();\nif (results.length !== Math.max(1, contract.messages.length))\n    throw new Error('MESSAGE_ARCHIVE_RESULT_COUNT_MISMATCH');\nfor (const row of results) {\n    for (const field of ['run_id', 'source_code', 'window_start', 'run_upper_bound'])\n        if (row[field] !== contract[field])\n            throw new Error('MESSAGE_ARCHIVE_CONTEXT_MISMATCH:' + field);\n    if (row.archive_ready !== true || row.attachment_ids_verified !== true\n        || row.attachment_verification_barrier !== 'VERIFIED' || row.email_evidence_receipt_barrier !== 'VERIFIED')\n        throw new Error('MESSAGE_ARCHIVE_PROOF_REQUIRED');\n}\nconst emails = results.flatMap(row => row.email_evidence_identity_keys || []).sort();\nconst attachments = results.flatMap(row => row.attachment_identity_keys || []).sort();\nif (JSON.stringify(emails) !== JSON.stringify(expectedEmails) || JSON.stringify(attachments) !== JSON.stringify(expectedAttachments)\n    || results.reduce((sum, row) => sum + Number(row.email_evidence_receipts_verified), 0) !== emails.length\n    || results.reduce((sum, row) => sum + Number(row.attachments_verified), 0) !== attachments.length)\n    throw new Error('MESSAGE_ARCHIVE_IDENTITIES_OR_COUNTS_MISMATCH');\nreturn [{ json: { ...contract, status: 'ARCHIVED', archive_ready: true,\n            attachment_ids_verified: true, attachment_verification_barrier: 'VERIFIED', attachment_identity_keys: attachments,\n            attachments_verified: attachments.length, email_evidence_receipt_barrier: 'VERIFIED',\n            email_evidence_identity_keys: emails, email_evidence_receipts_verified: emails.length,\n            email_evidence_archive_proof: results.flatMap(row => row.email_evidence_archive_proof || []),\n            attachment_archive_proof: results.flatMap(row => row.attachment_archive_proof || []),\n            archive_identity_keys: [...attachments, ...emails].sort(),\n            archive_item_ids: [...new Set(results.flatMap(row => row.archive_item_ids || []))].sort(),\n            cursor_commit_eligible: false } }];\n","name":"Aggregate Verified Message Archives"},{"code":"OUTLOOK_MESSAGE_SWEEP","js":"// Purpose: Return Verified ARCHIVED Receipt. Keep this deterministic and fail closed.\nconst expected = $('Verify ARCHIVED Acquisition Receipt').first().json, observed = $json;\nconst inventory = $('Attach Immutable Inventory to Sweep').first().json;\nfor (const field of ['run_id', 'source_code', 'window_start', 'run_upper_bound', 'terminal_state', 'downstream_receipt_sha256'])\n    if (String(observed[field] ?? '') !== String(expected[field] ?? ''))\n        throw new Error('ARCHIVED_RECEIPT_TERMINAL_READBACK_MISMATCH:' + field);\nfor (const field of ['run_id', 'source_code', 'window_start', 'run_upper_bound'])\n    if (String(observed[field] ?? '') !== String(inventory[field] ?? ''))\n        throw new Error('ARCHIVED_RECEIPT_INVENTORY_BINDING_MISMATCH:' + field);\nif (observed.readback_verified !== true || observed.archive_ready !== true)\n    throw new Error('ARCHIVED_RECEIPT_TERMINAL_STATE_MISMATCH');\nfor (const field of ['attachment_verification_barrier', 'attachment_ids_verified', 'attachment_identity_keys_json', 'attachments_verified', 'email_evidence_receipt_barrier', 'email_evidence_receipts_verified', 'email_evidence_identity_keys_json'])\n    if (JSON.stringify(observed[field]) !== JSON.stringify(expected[field]))\n        throw new Error('ARCHIVED_RECEIPT_TERMINAL_BARRIER_MISMATCH:' + field);\nreturn [{ json: { ...inventory, ...expected, ...observed, messages: inventory.messages,\n            attachment_archive_proof: expected.attachment_archive_proof || [],\n            immutable_inventory: true, readback_verified: true, receipt_readback_verified: true, cursor_commit_eligible: false } }];\n","name":"Return Verified ARCHIVED Receipt"},{"code":"SHARED_MONTHLY_STATEMENT_CYCLE","js":"// Purpose: Select Verified Monthly Statement. Keep this deterministic and fail closed.\nconst archive = $json;\nif (archive.archive_ready !== true || archive.receipt_readback_verified !== true\n    || archive.attachment_verification_barrier !== 'VERIFIED' || archive.pagination_exhausted !== true)\n    throw new Error('MONTHLY_ARCHIVE_READBACK_REQUIRED');\nconst proofs = archive.attachment_archive_proof;\nif (!Array.isArray(proofs) || !Array.isArray(archive.attachment_identity_keys))\n    throw new Error('MONTHLY_ATTACHMENT_PROOFS_REQUIRED');\nconst identities = proofs.map(row => row.attachment_identity).sort();\nif (new Set(identities).size !== identities.length\n    || JSON.stringify(identities) !== JSON.stringify(archive.attachment_identity_keys.slice().sort()))\n    throw new Error('MONTHLY_ATTACHMENT_PROOF_COVERAGE_MISMATCH');\nfor (const row of proofs) {\n    if (!row.source_message_id || !row.source_attachment_id\n        || row.attachment_identity !== row.source_message_id + ':' + row.source_attachment_id\n        || !/^[a-f0-9]{64}$/.test(String(row.document_sha256 || '')) || !row.onedrive_item_id\n        || typeof row.is_pdf !== 'boolean' || typeof row.is_inline !== 'boolean')\n        throw new Error('MONTHLY_ATTACHMENT_PROOF_INVALID');\n}\nconst candidates = proofs.filter(row => row.is_pdf && !row.is_inline);\nconst hashes = new Set(candidates.map(row => row.document_sha256));\nif (hashes.size > 1)\n    throw new Error('MONTHLY_STATEMENT_AMBIGUOUS_DISTINCT_PDFS_REVIEW_REQUIRED');\nconst selected = candidates.slice().sort((a, b) => a.attachment_identity.localeCompare(b.attachment_identity))[0];\nreturn [{ json: { ...archive, monthly_statement: selected || null,\n    monthly_statement_source_identities: candidates.map(row => row.attachment_identity).sort(),\n    onedrive_item_id: selected?.onedrive_item_id || null } }];\n","name":"Select Verified Monthly Statement","node":{"id":"monthly-select-verified-pdf","name":"Select Verified Monthly Statement","parameters":{"jsCode":"// Purpose: Select Verified Monthly Statement. Fail before any financial write on ambiguous PDFs.\nconst archive = $json;\nif (archive.archive_ready !== true || archive.receipt_readback_verified !== true\n    || archive.attachment_verification_barrier !== 'VERIFIED' || archive.pagination_exhausted !== true)\n    throw new Error('MONTHLY_ARCHIVE_READBACK_REQUIRED');\nconst proofs = archive.attachment_archive_proof;\nif (!Array.isArray(proofs) || !Array.isArray(archive.attachment_identity_keys))\n    throw new Error('MONTHLY_ATTACHMENT_PROOFS_REQUIRED');\nconst identities = proofs.map(row => row.attachment_identity).sort();\nif (new Set(identities).size !== identities.length\n    || JSON.stringify(identities) !== JSON.stringify(archive.attachment_identity_keys.slice().sort()))\n    throw new Error('MONTHLY_ATTACHMENT_PROOF_COVERAGE_MISMATCH');\nfor (const row of proofs) {\n    if (!row.source_message_id || !row.source_attachment_id\n        || row.attachment_identity !== row.source_message_id + ':' + row.source_attachment_id\n        || !/^[a-f0-9]{64}$/.test(String(row.document_sha256 || '')) || !row.onedrive_item_id\n        || typeof row.is_pdf !== 'boolean' || typeof row.is_inline !== 'boolean')\n        throw new Error('MONTHLY_ATTACHMENT_PROOF_INVALID');\n}\nconst candidates = proofs.filter(row => row.is_pdf && !row.is_inline);\nconst hashes = new Set(candidates.map(row => row.document_sha256));\nif (hashes.size > 1)\n    throw new Error('MONTHLY_STATEMENT_AMBIGUOUS_DISTINCT_PDFS_REVIEW_REQUIRED');\nconst selected = candidates.slice().sort((a, b) => a.attachment_identity.localeCompare(b.attachment_identity))[0];\nreturn [{ json: { ...archive, monthly_statement: selected || null,\n    monthly_statement_source_identities: candidates.map(row => row.attachment_identity).sort(),\n    onedrive_item_id: selected?.onedrive_item_id || null } }];\n"},"position":[830,0],"type":"n8n-nodes-base.code","typeVersion":2}},{"code":"SHARED_MONTHLY_STATEMENT_CYCLE","js":"// Purpose: Assemble Immutable Pipeline Input. Keep this deterministic and fail closed.\nconst c = $('Assemble Trusted Acquisition Contract').first().json;\nconst r = $('Select Verified Monthly Statement').first().json;\nconst proof = r.monthly_statement;\nif (!proof || $json.monthly_download_sha256 !== proof.document_sha256)\n    throw new Error('MONTHLY_DOWNLOADED_STATEMENT_HASH_MISMATCH');\nreturn [{ json: { ...c, ...r, document_sha256: proof.document_sha256,\n    onedrive_item_id: proof.onedrive_item_id, message_id: proof.source_message_id,\n    source_message_id: proof.source_message_id, attachment_id: proof.source_attachment_id,\n    source_attachment_id: proof.source_attachment_id }, binary: $binary }];\n","name":"Assemble Immutable Pipeline Input"},{"code":"SHARED_MONTHLY_STATEMENT_CYCLE","js":"// Purpose: Build W12 COMMIT Request. Keep this deterministic and fail closed.\nconst source = $('Assemble Trusted Acquisition Contract').first().json, archive = $('Acquire Archive and Read Back').first().json, pipeline = $('Run Shared Statement Pipeline').first().json, cursor = $json;\nconst receiptHash = String(pipeline.receipt_sha256 || '');\nif (pipeline.state !== 'SUCCEEDED' || pipeline.terminal_readback_verified !== true || pipeline.run_id !== source.run_id || pipeline.source_code !== source.source_code || !/^[a-f0-9]{64}$/.test(receiptHash))\n    throw new Error('DOWNSTREAM_TERMINAL_RECEIPT_REQUIRED');\nif (archive.archive_ready !== true || archive.attachment_verification_barrier !== 'VERIFIED' || archive.email_evidence_receipt_barrier !== 'VERIFIED' || archive.receipt_readback_verified !== true || archive.cursor_commit_eligible !== false)\n    throw new Error('ARCHIVE_BARRIER_REQUIRED_BEFORE_CURSOR_COMMIT');\nconst archiveHash = String(archive.downstream_receipt_sha256 || '');\nif (!/^[a-f0-9]{64}$/.test(archiveHash))\n    throw new Error('ARCHIVE_COMMIT_RECEIPT_HASH_REQUIRED');\nconst observedVersion = Number(cursor.cursor_version), sameRun = cursor.committed_run_id === source.run_id, sameWindow = cursor.cursor_value === source.run_upper_bound && cursor.run_upper_bound === source.run_upper_bound;\nif (cursor.source_code !== source.source_code || !Number.isInteger(observedVersion) || observedVersion < 0)\n    throw new Error('SOURCE_CURSOR_READBACK_REQUIRED');\nif (sameRun && !sameWindow)\n    throw new Error('SOURCE_CURSOR_RECOVERY_WINDOW_MISMATCH');\nif (sameRun && observedVersion < 1)\n    throw new Error('SOURCE_CURSOR_RECOVERY_VERSION_INVALID');\nconst expected = sameRun && sameWindow ? observedVersion - 1 : observedVersion;\nreturn [{ json: { ...archive, ...source, operation: 'COMMIT', expected_cursor_version: expected, downstream_receipt_sha256: archiveHash, pipeline_receipt_sha256: receiptHash, attachment_verification_barrier: archive.attachment_verification_barrier, email_evidence_receipt_barrier: archive.email_evidence_receipt_barrier, email_evidence_receipts_verified: Number(archive.email_evidence_receipts_verified), archive_ready: true, receipt_readback_verified: archive.receipt_readback_verified, cursor_commit_eligible: false, pipeline_terminal_readback_verified: true } }];\n","name":"Build W12 COMMIT Request"},{"code":"OUTLOOK_MESSAGE_SWEEP","name":"Verify ARCHIVED Acquisition Receipt","js":"// Purpose: Verify ARCHIVED Acquisition Receipt. Keep this deterministic and fail closed.\nconst expected = $('Build Durable Archive Barrier Receipt').first().json, hash = $('SHA-256 Durable Archive Barrier Receipt').first().json.downstream_receipt_sha256, observed = $json;\nfor (const field of ['run_id', 'source_code', 'window_start', 'run_upper_bound', 'terminal_state', 'downstream_receipt_sha256'])\n    if (String(observed[field] ?? '') !== String(field === 'downstream_receipt_sha256' ? hash : field === 'terminal_state' ? 'ARCHIVED' : expected[field] ?? ''))\n        throw new Error('ARCHIVED_RECEIPT_READBACK_MISMATCH:' + field);\nif (observed.archive_ready !== true || observed.readback_verified !== false)\n    throw new Error('ARCHIVED_RECEIPT_STATE_MISMATCH');\nfor (const field of ['attachment_verification_barrier', 'attachment_ids_verified', 'attachment_identity_keys_json', 'attachments_verified', 'email_evidence_receipt_barrier', 'email_evidence_receipts_verified', 'email_evidence_identity_keys_json'])\n    if (JSON.stringify(observed[field]) !== JSON.stringify(expected[field]))\n        throw new Error('ARCHIVED_RECEIPT_BARRIER_MISMATCH:' + field);\nreturn [{ json: { ...observed, attachment_archive_proof: expected.attachment_archive_proof || [], readback_verified: true, receipt_readback_verified: false } }];\n"}],"extra_nodes":[{"id":"monthly-hash-downloaded-pdf","name":"SHA-256 Monthly Statement Readback","parameters":{"action":"hash","binaryData":true,"binaryPropertyName":"data","dataPropertyName":"monthly_download_sha256","type":"SHA256"},"position":[-970,380],"type":"n8n-nodes-base.crypto","typeVersion":1}],"connections":{"Acquire Archive and Read Back":{"main":[[{"index":0,"node":"Select Verified Monthly Statement","type":"main"}]]},"Select Verified Monthly Statement":{"main":[[{"index":0,"node":"Statement Found","type":"main"}]]},"Download Archived Source":{"main":[[{"index":0,"node":"SHA-256 Monthly Statement Readback","type":"main"}]]},"SHA-256 Monthly Statement Readback":{"main":[[{"index":0,"node":"Assemble Immutable Pipeline Input","type":"main"}]]}}}''')


def ensure_monthly_archive_contract(workflows):
    by_code = {workflow["meta"]["financeWorkflowCode"]: workflow for workflow in workflows}
    for edit in CONTRACT["edits"]:
        workflow = by_code[edit["code"]]
        node = next((node for node in workflow["nodes"] if node["name"] == edit["name"]), None)
        if node is None:
            node = deepcopy(edit["node"])
            workflow["nodes"].append(node)
        node["parameters"]["jsCode"] = edit["js"]
    monthly = by_code["SHARED_MONTHLY_STATEMENT_CYCLE"]
    for node in CONTRACT["extra_nodes"]:
        if not any(existing["name"] == node["name"] for existing in monthly["nodes"]):
            monthly["nodes"].append(deepcopy(node))
    monthly["connections"].update(deepcopy(CONTRACT["connections"]))
